sparql_tries.sparql:
SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campno ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mn .
  FILTER(UCASE(STR(?mn)) IN ("HYUNDAI","KIA","GENESIS"))
} ORDER BY ?campno

SELECT ?campaignNumber (COUNT(DISTINCT ?makeName) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes) WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI","KIA","GENESIS"))
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?n .
  FILTER(?n IN ("HYUNDAI","KIA","GENESIS"))
  FILTER(?d >= "2023-01-01"^^<http://www.w3.org/2001/XMLSchema#date> && ?d < "2024-01-01"^^<http://www.w3.org/2001/XMLSchema#date>)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?r a rc:RecallCampaign ; rc:affectsComponent ?c ; rc:affects ?v .
  ?v rc:ofModel ?model .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?up }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)
LIMIT 5

SELECT ?topName (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v ; rc:affectsComponent ?comp .
  ?v rc:ofModel ?m . ?m rc:ofMake ?mk . ?mk rc:name "GENESIS" .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?up }
  ?top rc:name ?topName .
} GROUP BY ?topName ORDER BY DESC(?n)

SELECT (COUNT(DISTINCT ?yr) AS ?count) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v .
  ?v rc:ofModel ?m ; rc:modelYear ?yr .
  ?m rc:name "SONATA" ; rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ; rc:reportReceivedDate ?d ; rc:affects ?v .
  ?v rc:ofModel ?m . ?m rc:ofMake ?mk . ?mk rc:name ?mn .
  FILTER(?mn IN ("HYUNDAI","KIA","GENESIS"))
  BIND(YEAR(?d) AS ?year)
} GROUP BY ?year ORDER BY DESC(?n) LIMIT 1

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ; rc:campaignNumber ?campno .
  { ?r rc:defectSummary ?t } UNION { ?r rc:consequenceSummary ?t } UNION { ?r rc:rootCause ?t }
  FILTER(REGEX(STR(?t), "hydrogen", "i"))
}
ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ; rc:campaignNumber ?campno .
  OPTIONAL { ?c rc:defectSummary ?d }
  OPTIONAL { ?c rc:affectsComponent/rc:name ?cn }
  FILTER (regexp(?d, "ICCU|integrated charging control", "i") || regexp(?cn, "ICCU|INTEGRATED CHARGING", "i"))
} ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ; rc:campaignNumber ?campno .
  OPTIONAL { ?c rc:defectSummary ?d }
  OPTIONAL { ?c rc:affectsComponent ?comp . ?comp rc:name ?cn }
  FILTER (REGEX(STR(?d), "ICCU|integrated charging control", "i") || REGEX(STR(?cn), "ICCU|INTEGRATED CHARGING", "i"))
} ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campno .
  { ?r rc:defectSummary ?t } UNION { ?r rc:rootCause ?t } UNION { ?r rc:consequenceSummary ?t }
  FILTER(REGEX(?t, "water|moisture|liquid", "i") && REGEX(?t, "tow|trailer|hitch", "i"))
} ORDER BY ?campno
